const resp = $.steps.listSites.response || [];
const sites = (Array.isArray(resp) ? resp : []).map(s => ({
  id: s.id || '',
  name: s.name || '',
  url: s.ssl_url || s.url || '',
  adminUrl: s.admin_url || '',
  state: s.state || '',
  createdAt: s.created_at || '',
  updatedAt: s.updated_at || ''
}));

return {
  sites,
  totalSites: sites.length,
  summary: `Found ${sites.length} Netlify site${sites.length === 1 ? '' : 's'}`
};
